import numpy as np
import pandas as pd

def task_func(df, letter):
    if not isinstance(df, pd.DataFrame):
        df = pd.DataFrame(df)

    if "Word" not in df.columns:
        return {"mean": np.nan, "median": np.nan, "mode": np.nan}

    words = df["Word"].dropna().astype(str)
    matched = words[words.str.startswith(str(letter), na=False)]
    lengths = matched.str.len()

    if lengths.empty:
        return {"mean": np.nan, "median": np.nan, "mode": np.nan}

    mode_values = lengths.mode()

    return {
        "mean": float(lengths.mean()),
        "median": float(lengths.median()),
        "mode": float(mode_values.iloc[0]) if not mode_values.empty else np.nan,
    }
